export const getGetTrendUrl = (params: GetTrendParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/admin/trends?${stringifiedParams}` : `/api/admin/trends`
}

/**
 * @summary Get a daily report trend for a location and symptom
 */
export const getTrend = async (params: GetTrendParams, options?: Parameters<typeof customFetch>[1]): Promise<TrendPoint[]> => {

  return customFetch<TrendPoint[]>(getGetTrendUrl(params),
  {
    ...options,
    method: 'GET'


  }
);}





